{"content": "import os
import re
import sys
import urllib.parse

root = sys.argv[1]
link_re = re.compile(r'\[([^\]]*)\]\(([^)]+)\)')
skip_prefix = ('http://', 'https://', 'mailto:', 'tel:', '#')

all_md = set()
for dp, dns, fns in os.walk(root):
    dns[:] = [d for d in dns if d != '.git']
    for fn in fns:
        if fn.endswith('.md'):
            all_md.add(os.path.normpath(os.path.join(dp, fn)))

broken = []
total = 0
targets_from_index = set()
for dp, dns, fns in os.walk(root):
    dns[:] = [d for d in dns if d != '.git']
    for fn in fns:
        if not fn.endswith('.md'):
            continue
        p = os.path.join(dp, fn)
        txt = open(p, encoding='utf-8', errors='replace').read()
        for m in link_re.finditer(txt):
            tgt = m.group(2).strip()
            if tgt.startswith(skip_prefix):
                continue
            tgt = urllib.parse.unquote(tgt.split('#')[0].strip())
            if not tgt:
                continue
            total += 1
            full = os.path.normpath(os.path.join(dp, tgt))
            if not os.path.exists(full):
                broken.append((os.path.relpath(p, root), tgt))
            elif os.path.relpath(p, root) == 'README.md' and full in all_md:
                targets_from_index.add(full)

print("md_total=%d links=%d broken=%d" % (len(all_md), total, len(broken)))
if broken:
    for f, t in broken[:20]:
        print("BROKEN %s -> %s" % (f, t))

print("--- 未被 docs/README.md 直接链接的 md ---")
miss = sorted(os.path.relpath(m, root) for m in all_md - targets_from_index)
if not miss:
    print("(none) — 索引直接覆盖全部 md")
for m in miss:
    print("  %s" % m)
